def carry_payments_forward(apps, schema_editor):
    Booking = apps.get_model('Tour_travels', 'Booking')
    Payment = apps.get_model('Tour_travels', 'Payment')
    Payment.objects.exclude(status='completed').delete()
    for booking in Booking.objects.all():
        paid = sum((p.amount for p in Payment.objects.filter(booking=booking)), 0)
        if paid <= 0:
            booking.payment_status = 'unpaid'
        elif paid >= booking.total_price:
            booking.payment_status = 'paid'
        else:
            booking.payment_status = 'partial'
        booking.save(update_fields=['payment_status'])


